function Fixture(){const[value,setValue]=useState('A **saved** experience with an [example](https://example.com).');const[error,setError]=useState('');return <div className="portal-shell"><main style={{maxWidth:820,margin:'auto',padding:16}}><div className="procedure-ui"><section className="procedure-editor-page studio writing-document"><section className="procedure-composer studio-composer"><input className="document-title" aria-label="Title" placeholder="Untitled experience"/><RichExperienceEditor value={value} onChange={setValue} onLimit={()=>setError('Too long')} disabled={false} invalid={false}/></section></section></div><output data-testid="stored-markdown">{value}</output>{error&&<p role="alert">{error}</p>}<button onClick={()=>setValue('## Saved heading\n\nSaved **bold** content.\n\n| One | Two |\n| --- | --- |\n| A | B |')}>Load saved document</button></main></div>};createRoot(document.getElementById('root')!).render(<Fixture/>);
